import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    meetings = [(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n)]
    best = 0
    for mask in range(1 << n):
        chosen = [meetings[i] for i in range(n) if mask >> i & 1]
        if len(chosen) <= best:
            continue
        chosen.sort()
        ok = True
        for k in range(1, len(chosen)):
            if chosen[k][0] < chosen[k - 1][1]:
                ok = False
                break
        if ok:
            best = len(chosen)
    print(best)


main()
